-- A foreign key's `ON UPDATE CASCADE` writes the child's new key through its indexes: a
-- child index over `(k, pad)` refuses the cascaded row.
-- @setup
CREATE TABLE p (k text PRIMARY KEY);
CREATE TABLE c (k text REFERENCES p(k) ON UPDATE CASCADE, pad text);
CREATE INDEX c_i ON c (k, pad);
INSERT INTO p VALUES ('');
INSERT INTO c VALUES ('', '');
-- @test
-- @expect-error: the cascaded write refuses an oversized child key
-- @expect-message
-- @profile-lock
UPDATE p SET k = '';
